import { Component, OnInit } from '@angular/core';
import { Produto, ProdutoService } from '../../services/produto.service';

@Component({
  selector: 'app-lista-produtos',
  templateUrl: './lista-produtos.component.html',
  styleUrls: ['./lista-produtos.component.css']
})
export class ListaProdutosComponent implements OnInit {
  produtos: Produto[] = [];
  mensagemErro: string = '';
  mensagemSucesso: string = '';
  carregando: boolean = false;

  constructor(private produtoService: ProdutoService) {}

  ngOnInit(): void {
    this.carregarProdutos();
  }

  carregarProdutos(): void {
    this.carregando = true;
    this.produtoService.listar().subscribe({
      next: (dados) => {
        this.produtos = dados;
        this.carregando = false;
      },
      error: () => {
        this.mensagemErro = 'Erro ao carregar produtos. Verifique se o backend está rodando.';
        this.carregando = false;
      }
    });
  }

  remover(id: number, nome: string): void {
    if (!confirm(`Deseja remover o produto "${nome}"?`)) return;

    this.produtoService.remover(id).subscribe({
      next: () => {
        this.mensagemSucesso = `Produto "${nome}" removido com sucesso!`;
        this.mensagemErro = '';
        this.carregarProdutos();
        setTimeout(() => this.mensagemSucesso = '', 3000);
      },
      error: (err) => {
        this.mensagemErro = err.error?.mensagem || 'Erro ao remover produto.';
        this.mensagemSucesso = '';
      }
    });
  }
}
<div class="page-header">
  <h2>Lista de Produtos</h2>
</div>

<div class="alert alert-sucesso" *ngIf="mensagemSucesso">{{ mensagemSucesso }}</div>
<div class="alert alert-erro" *ngIf="mensagemErro">{{ mensagemErro }}</div>

<div class="carregando" *ngIf="carregando">Carregando...</div>

<div *ngIf="!carregando && produtos.length === 0 && !mensagemErro" class="vazio">
  Nenhum produto cadastrado. <a routerLink="/novo-produto">Cadastre um produto</a>.
</div>

<table *ngIf="produtos.length > 0" class="tabela">
  <thead>
    <tr>
      <th>#</th>
      <th>Nome</th>
      <th>Tipo</th>
      <th>Preço</th>
      <th>Ações</th>
    </tr>
  </thead>
  <tbody>
    <tr *ngFor="let produto of produtos">
      <td>{{ produto.id }}</td>
      <td>{{ produto.nome }}</td>
      <td><span class="badge">{{ produto.tipoProdutoNome }}</span></td>
      <td>{{ produto.preco | currency:'BRL':'symbol':'1.2-2' }}</td>
      <td>
        <button class="btn btn-remover" (click)="remover(produto.id, produto.nome)">Remover</button>
      </td>
    </tr>
  </tbody>
</table>
